/**
 * Java DTO 生成器
 * IR → record（视图 → DTO）
 *
 * 输出：generated/dto/LoginForm.java, LoginData.java
 */
import { writeFileSync, mkdirSync, existsSync } from 'fs'
import { join } from 'path'

const HEADER = [
  '// AUTO-GENERATED by polyforge. DO NOT EDIT.',
  '// 源：模型定义',
  '',
]

// 包名由 generateJavaDto 的 basePackage 参数派生（见文件末尾）

const PRIM = {
  id: 'String', string: 'String', text: 'String',
  int: 'Integer', long: 'Long',
  number: 'BigDecimal', decimal: 'BigDecimal',
  boolean: 'Boolean',
  date: 'LocalDate', datetime: 'OffsetDateTime',
  json: 'Object', array: 'List<Object>',
}

function javaType(fd) {
  if (fd.of) {
    if (PRIM[fd.of]) return 'List<' + PRIM[fd.of] + '>'
    if (fd.of === 'id') return 'List<String>'
    return 'List<' + javaTypeByRef(fd.of, fd.resolvedOf) + '>'
  }
  const t = fd.type
  if (PRIM[t]) return PRIM[t]
  return javaTypeByRef(t, fd.resolved)
}

/** 引用类型映射（enum/view/entity）。其余 kind 由 C3 拦截，到不了这里。 */
function javaTypeByRef(name, resolved) {
  if (resolved.kind === 'enum' || resolved.kind === 'view' || resolved.kind === 'entity') return name
  throw new Error('无法映射 DTO 字段引用类型: ' + name + '（kind=' + resolved.kind + '）')
}

function renderDto(name, def, PKG, PKG_ENUM) {
  const fields = def.fields || {}
  const lines = [...HEADER]
  lines.push('package ' + PKG + ';')
  lines.push('')

  // 收集用到的类型 import
  const usedEnums = new Set()
  const usedViews = new Set()
  let needsBigDecimal = false
  let needsList = false
  let needsDate = false
  let needsDateTime = false

  const params = []
  for (const [fn, fd] of Object.entries(fields)) {
    if (fd.writeOnly && def.viewKind !== 'form') continue
    const t = javaType(fd)
    if (t === 'BigDecimal') needsBigDecimal = true
    if (t.startsWith('List<')) needsList = true
    if (t === 'LocalDate') needsDate = true
    if (t === 'OffsetDateTime') needsDateTime = true
    if (fd.resolved?.kind === 'enum') usedEnums.add(fd.resolved.target)
    if (fd.resolved?.kind === 'view') usedViews.add(fd.resolved.target)
    if (fd.resolvedOf?.kind === 'enum') usedEnums.add(fd.resolvedOf.target)
    if (fd.resolvedOf?.kind === 'view') usedViews.add(fd.resolvedOf.target)
    if (fd.derived) lines.push('    // derived(' + fd.derived + '): 由 Service 装配，映射器不填充')
    params.push('        ' + t + ' ' + fn)
  }

  lines.push('import java.time.OffsetDateTime;')
  lines.push('import java.time.LocalDate;')
  lines.push('import java.math.BigDecimal;')
  lines.push('import java.util.List;')
  for (const e of [...usedEnums].sort()) {
    lines.push('import ' + PKG_ENUM + '.' + e + ';')
  }
  lines.push('')

  if (def.description) lines.push('/** ' + def.description + ' */')
  if (params.length === 0) {
    lines.push('public record ' + name + '() {}')
  } else {
    lines.push('public record ' + name + '(')
    lines.push(params.join(',\n'))
    lines.push(') {}')
  }
  return lines.join('\n') + '\n'
}

export function generateJavaDto(ir, outRoot, basePackage) {
  const PKG = basePackage + '.generated.dto'
  const PKG_ENUM = basePackage + '.generated.enums'
  const dir = join(outRoot, 'dto')
  if (!existsSync(dir)) mkdirSync(dir, { recursive: true })

  let count = 0
  for (const [name, def] of ir.views) {
    writeFileSync(join(dir, name + '.java'), renderDto(name, def, PKG, PKG_ENUM), 'utf-8')
    count++
  }
  console.log('  [java/dto] ' + count + ' 个 DTO → ' + dir)
}
